//! Deterministic section-1 manual pages using portable man(7) macros.
use super::{CONNECTION_DESCRIPTION, catalog};
use std::fmt::Write;

fn text(value: &str) -> String {
    // Prevent text from becoming roff requests or escape sequences.
    value
        .lines()
        .map(|line| format!("\\&{}", line.replace('\\', "\\e").replace('-', "\\-")))
        .collect::<Vec<_>>()
        .join("\n")
}

pub(super) fn render() -> String {
    let binary = "wgfeel";
    let purpose = "WireGuard mesh node and administration";
    let mut out = format!(
        ".\\\" Generated by cargo docs; do not edit.\n.TH {} 1 \"\" \"wgfeel {}\" \"User Commands\"\n.SH NAME\n{} \\- {purpose}\n.SH SYNOPSIS\n.B {binary}\nCOMMAND [OPTIONS]\n.SH DESCRIPTION\n",
        binary.to_ascii_uppercase(),
        env!("CARGO_PKG_VERSION"),
        text(binary)
    );
    out.push_str(&text("One executable supports main and child control capabilities. Main owns configuration and can also serve or relay user traffic. Children keep forwarding accepted traffic when main is unavailable. External HTTP REST uses its own TCP listener. Use --help or COMMAND --help for details."));
    {
        out.push_str("\n.SH CONNECTION\n");
        out.push_str(&text(CONNECTION_DESCRIPTION));
        for (option, description) in catalog::CONNECTION {
            writeln!(out, "\n.TP\n.B {}\n{}", text(option), text(description)).unwrap();
        }
    }
    out.push_str("\n.SH COMMANDS\n");
    for command in catalog::commands() {
        writeln!(
            out,
            ".SS {}\n.nf\n{}\n.fi\n.PP\n{}",
            if command.name.is_empty() {
                "Foreground Node"
            } else {
                command.name
            },
            text(&command.invocation()),
            text(command.description)
        )
        .unwrap();
        for (option, description) in command.options {
            writeln!(out, ".TP\n.B {}\n{}", text(option), text(description)).unwrap();
        }
        if !command.examples.is_empty() {
            out.push_str(".PP\nExamples:\n.nf\n");
            for example in command.examples {
                writeln!(out, "{}", text(example)).unwrap();
            }
            out.push_str(".fi\n");
        }
    }
    out.push_str(".SH FILES\n.TP\n.B /opt/wgfeel/instance\nConfiguration, state and owned executable for either control capability.\n.TP\n.B /etc/systemd/system/wgfeel.service\nInstalled system service.\n");
    out.push_str(".SH EXIT STATUS\nZero on success; nonzero on invalid input or failure.\n");
    out
}

#[cfg(test)]
mod tests {
    #[test]
    fn examples_fit_an_eighty_column_manual_and_have_valid_shell_syntax() {
        for command in super::catalog::commands() {
            for example in command.examples {
                for line in example.lines() {
                    // Leave room for man(7)'s indentation in an 80-column terminal.
                    assert!(
                        line.chars().count() <= 70,
                        "{} example exceeds manual width: {line}",
                        command.name
                    );
                }
                let output = std::process::Command::new("bash")
                    .args(["--noprofile", "--norc", "-n", "-c", example])
                    .output()
                    .unwrap();
                assert!(
                    output.status.success(),
                    "{} example has invalid shell syntax",
                    command.name
                );
            }
        }
    }
}
